const normalizeMedicalTerm = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
function localizeSpecialty(value){
  const direct=i18nT(value);
  const locale=window.DovelaI18n?.locale || 'es';
  if(locale==='es' || direct!==value || !SPECIALTY_COPY[locale]) return direct;
  const copy=SPECIALTY_COPY[locale];
  return String(value).split(/(\s*[-,]\s*)/).map(part=>{
    const phrase=copy.phrases[normalizeMedicalTerm(part)];
    if(phrase) return phrase;
    return part.replace(/\p{L}+/gu,word=>copy.words[normalizeMedicalTerm(word)] || word);
  }).join('');
}

