function pdfBlob(id){
  return window.DOVELA_FORMS[id].build().output('blob');
}
function descargarPDF(id){
  const a=document.createElement('a');
  a.href=URL.createObjectURL(pdfBlob(id)); a.download=window.DOVELA_FORMS[id].nombre; a.click();
  toast('Formulario descargado');
}
function abrirPDF(id){ window.open(URL.createObjectURL(pdfBlob(id)),'_blank'); }

