/* Genérico: lista de docs [nombre,req,multiple,maxMB], almacén de archivos, id contenedor, prefijo callbacks */
function pintarDoclist(contId, docs, store, fnName){
  $(contId).innerHTML = docs.map(([doc,req,multi,maxMB],i)=>{
    const files = store[i]||[];
    return `<div class="doc ${files.length?'ok':''}">
      <div class="info"><b>${i18nT(doc)}${req?' *':''}</b>
        <span>${i18nT(req?'Obligatorio':'Opcional')}${multi?' · '+i18nT('varios archivos'):''} · PDF, JPG o PNG · max. ${maxMB} MB</span>
        ${files.map(f=>`
    <span class="archivo">
        <span class=ico data-icon=check aria-hidden=true></span> ${f.name} (${(f.size/1024/1024).toFixed(1)} MB)
    </span>
`).join('')}
      </div>
      <div class="botones">
        <label class="btn btn-ghost btn-sm" style="margin:0"><span class=ico data-icon=carpeta aria-hidden=true></span> ${i18nT(files.length&&!multi?'Reemplazar':'Cargar')}
          <input type="file" ${multi?'multiple':''} accept=".pdf,.jpg,.jpeg,.png" onchange="${fnName}(${i},this,${maxMB},${multi})"></label>
        <label class="btn btn-ghost btn-sm" style="margin:0"><span class=ico data-icon=camara aria-hidden=true></span> ${i18nT('Tomar foto')}
          <input type="file" accept="image/*" capture="environment" onchange="${fnName}(${i},this,${maxMB},${multi})"></label>
      </div>
    </div>`;
  }).join('');
}

function cargarGenerico(
    store,
    i,
    input,
    maxMB,
    multi,
    repintar
){

    const nuevos = [];

    for(const f of input.files){

        if(
            f.size >
            maxMB * 1024 * 1024
        ){
            toast(i18nT('El archivo “{file}” supera el límite de {maxMB} MB.', { file: f.name, maxMB }));
            continue;

        }

        if(
            !/\.(pdf|jpe?g|png)$/i.test(f.name) &&
            !f.type.startsWith("image/")
        ){
            toast(
                "Formato no permitido."
            );
            continue;
        }
        nuevos.push(f);

    }

    if(!nuevos.length){
        input.value = "";
        return;
    }

    console.log("Antes de guardar:", store);

    console.log("Nuevos:", nuevos);

    store[i] = multi
        ? [
            ...(store[i] || []),
            ...nuevos
        ]
        : [
            nuevos[0]
        ];
    input.value = "";
    repintar();

    console.log("Después de guardar:", store);
}


