// Asignacion de siguiente codigo consecutivo incremental disponible caso colision de codigo en DB
 
function siguienteConsecutivo(){

    const hoy = new Date();

    const yy =
        String(hoy.getFullYear()).slice(-2);

    const inicio =
        new Date(
            hoy.getFullYear(),
            0,
            0
        );

    const juliano =
        String(
            Math.floor(
                (hoy - inicio) / 86400000
            )
        ).padStart(3, "0");

    const clave =
        `SGP-${yy}${juliano}`;

    const datos =
        JSON.parse(
            localStorage.getItem(
                "sgp_consecutivos"
            ) || "{}"
        );

    if(!datos[clave]){
        datos[clave] = 0;
    }

    /*
     * ESTA ES LA ÚNICA LÍNEA QUE
     * INCREMENTA EL CONSECUTIVO.
     */
    datos[clave]++;

    consecutivoReservado =
        datos[clave];

    localStorage.setItem(
        "sgp_consecutivos",
        JSON.stringify(datos)
    );

    console.log(
        "================================="
    );

    console.log(
        "[CONSECUTIVO] NUEVO CONSECUTIVO"
    );

    console.log(
        "[CONSECUTIVO] Clave:",
        clave
    );

    console.log(
        "[CONSECUTIVO] Número:",
        consecutivoReservado
    );

    console.log(
        "[CONSECUTIVO] Servicio:",
        wizard.servicio
    );

    console.log(
        "[CONSECUTIVO] Código:",
        obtenerCodigoReclamo()
    );

    console.log(
        "================================="
    );

    return consecutivoReservado;
}

