function obtenerJuliano(){

    const hoy = new Date();

    const inicio =
        new Date(
            hoy.getFullYear(),
            0,
            0
        );

    const dias =
        Math.floor(
            (hoy - inicio) / 86400000
        );

    const anio =
        String(
            hoy.getFullYear()
        ).slice(-2);

    const juliano =
        String(dias)
            .padStart(3,"0");

    return anio + juliano;
}

function obtenerJuliano(){

    const hoy = new Date();

    const inicio = new Date(
        hoy.getFullYear(),
        0,
        0
    );

    const dias = Math.floor(
        (hoy - inicio) / 86400000
    );

    const anio = String(
        hoy.getFullYear()
    ).slice(-2);

    const juliano = String(dias)
        .padStart(3,"0");

    return anio + juliano;

}


