function descargarBlob(blob, nombreArchivo){
  if(!(blob instanceof Blob) || blob.size === 0){
    throw new Error("El comprobante PDF está vacío.");
  }
  const url = URL.createObjectURL(blob);
  const enlace = document.createElement('a');
  enlace.href = url;
  enlace.download = nombreArchivo;
  enlace.hidden = true;
  document.body.appendChild(enlace);
  enlace.click();
  enlace.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 30000);
}

/* Fallback local: mantiene disponible el comprobante si la CDN de jsPDF falla. */
function crearComprobantePdfBasico(datos){
  const limpiar = valor => String(valor ?? "—")
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[–—]/g, '-')
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[^\x20-\x7E]/g, '?')
    .slice(0, 110);
  const escapar = valor => limpiar(valor).replace(/([\\()])/g, '\\$1');
  const filas = [
    ["/F2", 20, 56, 785, "Dovela Seguros"],
    ["/F1", 11, 56, 765, i18nT("Comprobante de Recepción de Reclamo")],
    ["/F2", 16, 56, 720, i18nT("Código de Reclamo")],
    ["/F2", 18, 56, 692, datos.codigo],
    ["/F2", 11, 56, 645, i18nT("Asegurado") + ":"],
    ["/F1", 11, 190, 645, datos.asegurado],
    ["/F2", 11, 56, 620, i18nT("Cédula") + ":"],
    ["/F1", 11, 190, 620, datos.cedula],
    ["/F2", 11, 56, 595, i18nT("Correo") + ":"],
    ["/F1", 11, 190, 595, datos.correo],
    ["/F2", 11, 56, 570, i18nT("Línea") + ":"],
    ["/F1", 11, 190, 570, i18nT(datos.linea)],
    ["/F2", 11, 56, 545, i18nT("Producto") + ":"],
    ["/F1", 11, 190, 545, i18nT(datos.producto)],
    ["/F2", 11, 56, 520, i18nT("Servicio") + ":"],
    ["/F1", 11, 190, 520, i18nT(datos.servicio)],
    ["/F2", 11, 56, 495, i18nT("Fecha del Evento") + ":"],
    ["/F1", 11, 190, 495, datos.fechaEvento],
    ["/F1", 10, 56, 430, i18nT("Conserve este documento para futuras consultas.")],
    ["/F1", 8, 56, 72, datos.generadoEn.toLocaleString(window.DovelaI18n?.locales?.[window.DovelaI18n.locale]?.tag || 'es-PA')]
  ];
  const contenido = filas.map(([fuente, tamano, x, y, texto]) =>
    `BT ${fuente} ${tamano} Tf 1 0 0 1 ${x} ${y} Tm (${escapar(texto)}) Tj ET`
  ).join('\n');
  const objetos = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>',
    `<< /Length ${contenido.length} >>\nstream\n${contenido}\nendstream`
  ];
  const partes = ['%PDF-1.4\n'];
  const offsets = [0];
  let longitud = partes[0].length;
  objetos.forEach((objeto, indice) => {
    offsets.push(longitud);
    const parte = `${indice + 1} 0 obj\n${objeto}\nendobj\n`;
    partes.push(parte);
    longitud += parte.length;
  });
  const inicioXref = longitud;
  partes.push(`xref\n0 ${objetos.length + 1}\n0000000000 65535 f \n`);
  offsets.slice(1).forEach(offset => partes.push(`${String(offset).padStart(10, '0')} 00000 n \n`));
  partes.push(`trailer\n<< /Size ${objetos.length + 1} /Root 1 0 R >>\nstartxref\n${inicioXref}\n%%EOF`);
  return new Blob([partes.join('')], { type: 'application/pdf' });
}


