function sincronizarRadioCards(contenedorId, valor){
  const grupo = $(contenedorId);
  if(!grupo) return;
  grupo.setAttribute('aria-invalid', 'false');
  grupo.querySelectorAll('.tipo').forEach(card => {
    const radio = card.querySelector('input[type="radio"]');
    const seleccionado = radio?.value === valor;
    if(radio) radio.checked = seleccionado;
    card.classList.toggle('sel', seleccionado);
  });
}

