/* ================= QR DE SEGUIMIENTO DEL COMPROBANTE ================= */
const PARAMETRO_SEGUIMIENTO = 'reclamo';

/* Dirección pública del portal. El QR siempre apunta aquí y no a location.origin: un comprobante
   generado en local (localhost, 127.0.0.1, file://) o en un deploy de preview de Vercel (protegido
   con login) llevaría al celular a una dirección que no puede abrir. */
const URL_PUBLICA_PORTAL = 'https://dovelaseguros.vercel.app/';

/* URL que abre la consulta de estado con el código precargado. La cédula nunca viaja en el QR:
   sigue siendo el segundo factor que el asegurado escribe en su celular. El idioma del comprobante
   viaja como ?lang= para que el portal abra en ese idioma sin mostrar el diálogo de idioma
   encima de la consulta. */
function urlSeguimientoReclamo(codigo){
  codigo = String(codigo || '').trim().toUpperCase();
  if(!/^SGP-[A-Z0-9-]{4,28}$/.test(codigo)) return null;
  const url = new URL(URL_PUBLICA_PORTAL);
  url.searchParams.set(PARAMETRO_SEGUIMIENTO, codigo);
  const idioma = window.DovelaI18n?.locale;
  if(idioma) url.searchParams.set('lang', idioma);
  return url.href;
}

/* Dibuja el QR como rectángulos vectoriales (nítido al imprimir). Une módulos oscuros contiguos
   de cada fila en un solo rectángulo para reducir el tamaño del PDF. */
function dibujarQrSeguimiento(pdf, texto, x, y, lado){
  if(!texto || typeof window.qrcode !== 'function') return false;
  const qr = window.qrcode(0, 'M');
  qr.addData(texto);
  qr.make();
  const total = qr.getModuleCount();
  const modulo = lado / total;
  pdf.setFillColor(15,23,42);
  for(let fila = 0; fila < total; fila++){
    let inicio = -1;
    for(let col = 0; col <= total; col++){
      const oscuro = col < total && qr.isDark(fila, col);
      if(oscuro && inicio < 0) inicio = col;
      if(!oscuro && inicio >= 0){
        // +0.02 mm de alto evita líneas finas entre filas en algunos visores.
        pdf.rect(x + inicio * modulo, y + fila * modulo, (col - inicio) * modulo, modulo + 0.02, 'F');
        inicio = -1;
      }
    }
  }
  return true;
}

//      Funcion de generacion de comprobante PDF <<-- </gishikoDev_> -->>
async function descargarTicketPDF(event){

    event?.preventDefault();
    const esActivacionUsuario = event?.type === 'click';
    if(esActivacionUsuario && descargaComprobanteEnCurso) return false;
    if(esActivacionUsuario) descargaComprobanteEnCurso = true;

    const boton = $('btn-pdf');
    if(boton && esActivacionUsuario){
        boton.disabled = true;
        boton.setAttribute('aria-busy', 'true');
    }
    actualizarEstadoDescargaComprobante('Preparando el comprobante PDF…');

    const datos = comprobanteReclamoActual || capturarDatosComprobante();
    const nombreArchivo = `${i18nT('Comprobante_Reclamo_Dovela')}_${datos.codigo}.pdf`;

    try {
      const jsPDF = window.jspdf?.jsPDF;
      if(!jsPDF){
        descargarBlob(crearComprobantePdfBasico(datos), nombreArchivo);
        actualizarEstadoDescargaComprobante('La descarga del comprobante comenzó.');
        toast('La descarga del comprobante comenzó.');
        return true;
      }

    const pdf = new jsPDF({
        orientation: "portrait",
        unit: "mm",
        format: "a4"
    });

    // ==========================================
    // COLORES
    // ==========================================

    // PulsePoint palette (DESIGN.md), print-safe on paper
    const VERDE = [21,128,61];    // success (print tone of #22C55E)
    const AZUL  = [30,58,95];     // Primary Navy
    const GRIS  = [51,65,85];     // slate text
    const CLARO = [248,250,252];  // paper
    const BORDE = [203,213,225];  // border

    // ==========================================
    // FONDO
    // ==========================================

    pdf.setFillColor(...CLARO);
    pdf.rect(0,0,210,297,"F");

    // ==========================================
    // CABECERA
    // ==========================================

    pdf.setFillColor(...AZUL);
    pdf.rect(0,0,210,26,"F");

    pdf.setTextColor(255,255,255);
    pdf.setFont("helvetica","bold");
    pdf.setFontSize(21);
    pdf.text("Dovela Seguros",20,15);

    pdf.setFont("helvetica","normal");
    pdf.setFontSize(10);
    pdf.text(
        i18nT("Comprobante de Recepción de Reclamo"),
        20,
        21
    );

    // ==========================================
    // TITULO
    // ==========================================

    pdf.setTextColor(...GRIS);

    pdf.setFont("helvetica","bold");
    pdf.setFontSize(18);

    pdf.text(
        i18nT("Comprobante"),
        20,
        42
    );

    pdf.setFont("helvetica","normal");
    pdf.setFontSize(10);

    pdf.text(
        i18nT("Conserve este documento para futuras consultas."),
        20,
        48
    );

    // ==========================================
    // TARJETA PRINCIPAL
    // ==========================================

    pdf.setFillColor(255,255,255);
    pdf.setDrawColor(...BORDE);

    pdf.roundedRect(
        15,
        55,
        180,
        130,
        4,
        4,
        "FD"
    );

    // ==========================================
    // CODIGO
    // ==========================================

    pdf.setTextColor(...GRIS);

    pdf.setFont("helvetica","bold");
    pdf.setFontSize(11);

    pdf.text(
        i18nT("Código de Reclamo"),
        25,
        70
    );

    pdf.setTextColor(...VERDE);

    pdf.setFont("courier","bold");
    pdf.setFontSize(22);

    pdf.text(
        datos.codigo,
        25,
        82
    );

    // ==========================================
    // LINEA DIVISORIA
    // ==========================================

    pdf.setDrawColor(...BORDE);

    pdf.line(
        25,
        90,
        185,
        90
    );

    // ==========================================
    // DATOS
    // ==========================================

    pdf.setTextColor(...GRIS);

    pdf.setFont("helvetica","bold");
    pdf.setFontSize(10);

    let y = 102;

    function fila(titulo,valor){

        pdf.setFont("helvetica","bold");
        pdf.text(titulo,25,y);

        pdf.setFont("helvetica","normal");
        // Los valores terminan antes del QR (x=150): un texto encima del código impediría escanearlo.
        const lineas = pdf.splitTextToSize(String(valor), 70);
        pdf.text(lineas.length > 1 ? lineas[0].trimEnd() + "..." : String(valor),72,y);

        y += 11;
    }

    fila(
        i18nT("Asegurado"),
        datos.asegurado
    );

    fila(
        i18nT("Cédula"),
        datos.cedula
    );

    fila(
        i18nT("Correo"),
        datos.correo
    );

    fila(
        i18nT("Línea"),
        i18nT(datos.linea)
    );

    fila(
        i18nT("Producto"),
        i18nT(datos.producto)
    );

    fila(
        i18nT("Servicio"),
        i18nT(datos.servicio)
    );

    fila(
        i18nT("Fecha del Evento"),
        datos.fechaEvento
    );

    // ==========================================
    // QR DE SEGUIMIENTO
    // ==========================================

    pdf.setDrawColor(...AZUL);

    pdf.roundedRect(
        150,
        118,
        32,
        32,
        2,
        2
    );

    // 26 mm dentro del marco de 32 mm: deja ~4 módulos de zona de silencio para la cámara.
    let qrDibujado = false;
    try {
        qrDibujado = dibujarQrSeguimiento(pdf, urlSeguimientoReclamo(datos.codigo), 153, 121, 26);
    } catch(errorQr) {
        console.warn('[PDF] No fue posible generar el código QR de seguimiento:', errorQr);
    }

    pdf.setFont("helvetica","bold");
    pdf.setFontSize(8);
    pdf.setTextColor(...AZUL);

    pdf.text(
        i18nT(qrDibujado ? "Escanee con su celular" : "Consulte el estado"),
        166,
        155,
        {
            align:"center"
        }
    );

    pdf.setFont("helvetica","normal");
    pdf.setFontSize(7.5);

    pdf.text(
        i18nT(qrDibujado ? "para seguir su reclamo" : "en el portal de Dovela"),
        166,
        159,
        {
            align:"center"
        }
    );

    // ==========================================
    // MENSAJE
    // ==========================================

    pdf.setTextColor(...GRIS);

    pdf.setFont("helvetica","normal");
    pdf.setFontSize(10);

    const texto = i18nT('Su reclamo ha sido recibido correctamente.\n\nEste comprobante confirma únicamente la recepción de la solicitud.\n\nConserve este documento hasta la resolución definitiva del caso.');

    pdf.text(
        texto,
        20,
        205
    );

    // ==========================================
    // PIE
    // ==========================================

    pdf.setDrawColor(...BORDE);
    pdf.line(
        20,
        270,
        190,
        270
    );

    pdf.setFont("helvetica","normal");
    pdf.setFontSize(8);

    pdf.setTextColor(120,120,120);

    pdf.text(
        i18nT("Portal de Reclamos Dovela Seguros • Generado automáticamente • Entidad ficticia con fines demostrativos"),
        20,
        278
    );

    pdf.text(
        datos.generadoEn.toLocaleString(window.DovelaI18n?.locales?.[window.DovelaI18n.locale]?.tag || 'es-PA'),
        190,
        278,
        {
            align:"right"
        }
    );

    if(typeof pdf.output === 'function'){
        descargarBlob(pdf.output('blob'), nombreArchivo);
    } else {
        pdf.save(nombreArchivo);
    }

    actualizarEstadoDescargaComprobante('La descarga del comprobante comenzó.');
    toast('La descarga del comprobante comenzó.');
    return true;

    } catch(error) {
      console.error('[PDF] No fue posible generar el comprobante:', error);
      actualizarEstadoDescargaComprobante('No pudimos generar el comprobante PDF. Inténtelo nuevamente.');
      toast('No pudimos generar el comprobante PDF. Inténtelo nuevamente.');
      return false;
    } finally {
      if(esActivacionUsuario){
        window.setTimeout(() => {
          descargaComprobanteEnCurso = false;
          if(boton){
            boton.disabled = false;
            boton.removeAttribute('aria-busy');
          }
        }, 900);
      }
    }

}

