function marca(id,ok){ const c=$(id).closest('.campo'); if(c) c.classList.toggle('invalido',!ok); return ok; }
function validarPaso(p){
  if(p===0){
    if(!wizard.perfil){
      $('err-perfil').style.display='block';
      $('perfiles').setAttribute('aria-invalid', 'true');
      $('perfiles').querySelector('input[type="radio"]')?.focus();
      return false;
    }
    return true;
  }
  if(p===1){
    if(!wizard.tipo){
        $('err-tipo').style.display='block';
        $('tipos').setAttribute('aria-invalid', 'true');
        $('tipos').querySelector('input[type="radio"]')?.focus();
        return false;
    }

    if(!wizard.servicio){
        $('err-servicio').style.display='block';
        document.querySelector('.servicios-grid')?.setAttribute('aria-invalid', 'true');
        document.querySelector('.servicios-grid input[type="radio"]')?.focus();
        return false;
    }

    return marca(
        'f-producto',
        $('f-producto').value!==''
    );
}
  if(p===2){
    let ok=true;
    ok = marca('f-nombre', $('f-nombre').value.trim().length>2) && ok;
    ok = marca('f-cedula', $('f-cedula').value.trim().length>3) && ok;
    ok = marca('f-tel', $('f-tel').value.trim().length>5) && ok;
    ok = marca('f-email', /.+@.+\..+/.test($('f-email').value)) && ok;
    if(wizard.perfil==='hospital') ok = marca('f-hospital', $('f-hospital').value.trim().length>2) && ok;
    return ok;
  }
  if(p===3){
    let ok = marca('f-fecha', $('f-fecha').value!=='');
    ok = marca('f-desc', $('f-desc').value.trim().length>10) && ok;
    const esHosp = wizard.perfil==='hospital';
    const montoOk = esHosp ? Number($('f-monto').value)>0 : ($('f-sinmonto').checked || $('f-monto').value==='' || Number($('f-monto').value)>0);
    $('campo-monto').classList.toggle('invalido', !montoOk);
    return ok && montoOk;
  }
  if(p===4){
    const faltan = DOCS[wizard.tipo][wizard.perfil].some(([_,req],i)=> req && !(wizard.archivos[i]||[]).length);
    $('err-docs').style.display = faltan?'block':'none';
    return !faltan;
  }
  if(p===5){
    const ok = $('f-consent').checked;
    $('err-consent').style.display = ok?'none':'block';
    return ok;
  }
  return true;
}

