/* ================= CONSULTA REAL DE ESTADO DE RECLAMO ================= */
let consultaReclamoEnCurso = false;
let consultaReclamoIntento = 0;

const DESCRIPCIONES_ESTADO_RECLAMO = {
  'Recibido': 'Hemos recibido su reclamo y comenzaremos su revisión.',
  'En Proceso': 'Nuestro equipo está revisando su reclamo.',
  'Pendiente de Información': 'Necesitamos información adicional. Revise el correo registrado en su solicitud.',
  'Pagado': 'El pago de su reclamo ha sido procesado. Consulte el detalle en la comunicación enviada a su correo.',
  'Rechazado': 'La evaluación ha concluido. Consulte la comunicación enviada a su correo para conocer los detalles.'
};

function abrirConsultaReclamo(){
  ir('v-claim-status');
  $('cs-title').focus();
}

function volverDeConsultaReclamo(){
  consultaReclamoIntento++;
  $('cs-form').reset();
  limpiarErroresConsulta();
  mensajeConsulta('', 'info');
  $('cs-result').hidden = true;
  ir('v-landing');
  $('card-seguimiento')?.focus();
}

/* Entrada desde el QR del comprobante: ?reclamo=SGP-… abre la consulta con el código precargado
   y deja el foco en la cédula, que el asegurado sigue escribiendo como comprobación. */
function abrirConsultaDesdeEnlace(){
  let codigo;
  try { codigo = new URLSearchParams(location.search).get(PARAMETRO_SEGUIMIENTO); } catch(_) { return; }
  if(!codigo) return;
  // Se retira el parámetro para que recargar o compartir la URL no reabra la consulta.
  const url = new URL(location.href);
  url.searchParams.delete(PARAMETRO_SEGUIMIENTO);
  history.replaceState(history.state, '', url.pathname + url.search + url.hash);
  abrirConsultaReclamo();
  codigo = codigo.trim().toUpperCase();
  if(!/^SGP-[A-Z0-9-]{4,28}$/.test(codigo)) return;
  $('cs-code').value = codigo;
  mensajeConsulta('Cargamos el código de su comprobante. Introduzca la cédula o pasaporte del asegurado para continuar.', 'info');
  $('cs-cedula').focus();
}

function limpiarErroresConsulta(){
  for(const id of ['code','cedula']){
    const input = $('cs-' + id);
    const error = $('cs-' + id + '-error');
    input.removeAttribute('aria-invalid');
    error.hidden = true;
    error.textContent = '';
  }
}

function errorCampoConsulta(id, mensaje){
  $('cs-' + id).setAttribute('aria-invalid','true');
  const error = $('cs-' + id + '-error');
  error.textContent = mensaje;
  error.hidden = false;
}

function mensajeConsulta(mensaje, tipo){
  const feedback = $('cs-feedback');
  feedback.textContent = mensaje;
  feedback.dataset.tipo = tipo || 'info';
  feedback.hidden = !mensaje;
}

function estadoCargaConsulta(activo){
  consultaReclamoEnCurso = activo;
  $('cs-form').setAttribute('aria-busy', String(activo));
  $('cs-submit').disabled = activo;
  $('cs-submit').textContent = activo ? 'Consultando…' : 'Consultar estado';
  $('cs-code').readOnly = activo;
  $('cs-cedula').readOnly = activo;
}

async function consultarEstadoReclamo(event){
  event.preventDefault();
  if(consultaReclamoEnCurso) return;

  limpiarErroresConsulta();
  $('cs-result').hidden = true;
  mensajeConsulta('', 'info');

  const codigo = $('cs-code').value.trim().toUpperCase();
  const cedula = $('cs-cedula').value.trim();
  $('cs-code').value = codigo;
  $('cs-cedula').value = cedula;

  let invalido = false;
  if(!codigo){ errorCampoConsulta('code','Introduzca el código de reclamo.'); invalido = true; }
  else if(!/^SGP-\d{5}-\d{4,}-[MDV]$/.test(codigo)){
    errorCampoConsulta('code','Verifique el formato del código de seguimiento.'); invalido = true;
  }
  if(!cedula){ errorCampoConsulta('cedula','Introduzca la cédula o pasaporte del asegurado.'); invalido = true; }
  else if(cedula.length <= 3){
    errorCampoConsulta('cedula','Verifique la cédula o pasaporte del asegurado.'); invalido = true;
  }
  if(invalido){
    $('cs-code').hasAttribute('aria-invalid') ? $('cs-code').focus() : $('cs-cedula').focus();
    return;
  }

  const intento = ++consultaReclamoIntento;
  estadoCargaConsulta(true);
  mensajeConsulta('Estamos consultando el estado de su reclamo.', 'info');
  try{
    const resultado = await ReclamosRepository.consultarEstado(codigo, cedula);
    if(intento !== consultaReclamoIntento) return;
    if(!resultado){
      mensajeConsulta('No pudimos verificar una solicitud con esos datos. Revise el código y la cédula e inténtelo nuevamente.', 'error');
      return;
    }
    $('cs-result-code').textContent = codigo;
    $('cs-result-state').textContent = resultado.estado;
    $('cs-result-state').className = 'badge ' + (BADGE[resultado.estado] || 'b-gris');
    $('cs-result-description').textContent = DESCRIPCIONES_ESTADO_RECLAMO[resultado.estado] || 'Consulte el correo registrado para recibir información sobre su solicitud.';
    $('cs-result-comment').hidden = !resultado.comentario;
    $('cs-result-comment-text').textContent = resultado.comentario || '';
    const fecha = resultado.actualizado_en ? new Date(resultado.actualizado_en) : null;
    const fechaValida = fecha && !Number.isNaN(fecha.getTime());
    $('cs-result-date').hidden = !fechaValida;
    if(fechaValida){
      $('cs-result-date').textContent = 'Última actualización: ' + new Intl.DateTimeFormat('es-PA',{dateStyle:'long'}).format(fecha);
    }
    $('cs-result').hidden = false;
    mensajeConsulta('Estado del reclamo: ' + resultado.estado + '.', 'success');
    $('cs-result').focus();
  }catch(error){
    if(intento !== consultaReclamoIntento) return;
    mensajeConsulta(navigator.onLine === false
      ? 'No hay conexión en este momento. Compruebe su conexión e inténtelo nuevamente.'
      : 'No pudimos consultar el estado en este momento. Inténtelo nuevamente más tarde.', 'error');
  }finally{
    estadoCargaConsulta(false);
  }
}

function consultarNuevamente(){
  $('cs-result').hidden = true;
  mensajeConsulta('', 'info');
  $('cs-code').focus();
}

/* ================= TRACKING (reclamos + pre-autorizaciones) ================= */
function buscarTracking(){
  const num = $('t-num').value.trim().toUpperCase();
  const id = $('t-id').value.trim().toLowerCase();
  let r=null, esPA=false;
  if(num.startsWith('PA-')){
    r = preauths.find(x=>x.num===num && (x.cedula.toLowerCase()===id || x.email.toLowerCase()===id));
    esPA=true;
  } else {
    r = reclamos.find(x=>x.num===num && (x.cedula.toLowerCase()===id || x.email.toLowerCase()===id));
  }
  $('t-error').style.display = r?'none':'block';
  $('t-resultado').classList.toggle('hidden', !r);
  if(!r) return;
  $('t-estado').textContent = r.estado;
  $('t-estado').className = 'badge ' + (BADGE[r.estado]||'b-gris');
  if(esPA){
    $('t-cabecera').innerHTML = `<b style="color:var(--text-primary)">${r.num}</b> · Pre-autorización · ${r.tipo}<br><span style="color:var(--pizarra);font-size:13px">Asegurado ${r.asegurado} · Recibida el ${r.recibido}</span>`;
    const flujo = ['Recibida','En evaluación', r.estado==='Negada'?'Negada':'Autorizada'];
    const idx = flujo.indexOf(r.estado);
    const notas = {'Recibida':'Su solicitud fue radicada en el portal.','En evaluación':'Nuestros médicos asesores están evaluando la solicitud.','Autorizada':'Autorización emitida. Válida por 30 días.','Negada':'Revise el correo con el detalle de la decisión.'};
    $('t-timeline').innerHTML = flujo.map((e,i)=>{
      const ev = r.bit.find(b=>b[0]===e);
      return `<div class="tl-item ${i<idx?'hecho':(i===idx?'actual':'')}"><b>${e}</b><span>${ev?ev[1]+' · ':''}${notas[e]}</span></div>`;
    }).join('');
    return;
  }
  $('t-cabecera').innerHTML = `<b style="color:var(--text-primary)">${r.num}</b> · ${lineaNombre(r.linea)} · ${productoActual(r.producto)} · ${r.nombre}<br><span style="color:var(--pizarra);font-size:13px">Recibido el ${r.recibido}${r.monto?' · Monto reclamado '+money(r.monto):''}</span>`;
  const notas = {'Recibido':'Su reclamo fue radicado y está en verificación de documentos.','En Proceso':'Registrado en nuestro sistema; el especialista analiza el reclamo según las condiciones de su póliza.','Pendiente de Información':'Necesitamos documentos o información adicional. Revise el correo con el detalle.','Pagado':'El pago fue procesado. Verá el detalle de la liquidación en su correo.','Rechazado':'El reclamo no procedió. Revise el correo con la explicación y sus opciones.'};
  let flujo;
  if(r.estado==='Rechazado') flujo=['Recibido','En Proceso','Rechazado'];
  else if(r.estado==='Pendiente de Información') flujo=['Recibido','Pendiente de Información','En Proceso','Pagado'];
  else flujo=['Recibido','En Proceso','Pagado'];
  const idx = flujo.indexOf(r.estado);
  $('t-timeline').innerHTML = flujo.map((e,i)=>{
    const ev = r.bit.find(b=>b[0]===e);
    const cls = i<idx?'hecho':(i===idx?(e==='Pendiente de Información'?'alerta':'actual'):'');
    return `<div class="tl-item ${cls}"><b>${e}</b><span>${ev?ev[1]+' · ':''}${notas[e]}</span></div>`;
  }).join('');
}

