/* ================= window.SC namespace v4 ================= */
window.SC = window.SC || {};

SC.validarFechaEvento = function(){
  if(wizard.tipo === 'VD') return true;
  const f = $('f-fecha'); const err = $('err-fecha');
  if(!f || !f.value){ if(err) err.classList.remove('vis'); return true; }
  const hoy = new Date(); hoy.setHours(0,0,0,0);
  const v = new Date(f.value);
  const diff = (hoy - v) / 86400000;
  const ok = (diff >= 0 && diff <= 365);
  f.style.borderColor = ok ? '' : 'var(--rojo)';
  if(err) err.classList.toggle('vis', !ok);
  if(!ok) toast('Solo se aceptan atenciones dentro de los últimos 365 días.');
  return ok;
};

// Ajustar fecha max/min al mostrar el paso de evento
SC.aplicarLimitesFecha = function(){
  const f = $('f-fecha'); if(!f) return;
  const hoy = new Date(); const min = new Date(); min.setDate(min.getDate()-365);
  f.max = hoy.toISOString().slice(0,10);
  f.min = min.toISOString().slice(0,10);
};

