// Documentos AP según sub-producto y tipo
SC.docsAP = function(subproducto, tipoAcc){
  const escolar = /Escolar/i.test(subproducto||'');
  const base = escolar
    ? [['Formulario firmado',1,0,10],['Certificado médico',1,0,10],['Reporte del accidente firmado y sellado por la escuela',1,0,10],['Cédula del representante',1,0,10]]
    : [['Formulario firmado',1,0,10],['Certificado médico',1,0,10],['Reporte del accidente',1,0,10],['Cédula del solicitante',1,0,10]];
  const opt = [['Facturas de gastos médicos',0,1,20],['Recetas médicas',0,1,20],['Resultados de exámenes',0,1,20],['Fotos del evento',0,1,20]];
  if(tipoAcc==='transito') base.push(['Reporte policial',1,1,20]);
  if(tipoAcc==='laboral') base.push(['Reporte CSS',1,1,20]);
  if(tipoAcc==='muerte'){ base.push(['Certificado de defunción',1,0,10]); opt.push(['Autopsia (si aplica)',0,0,20]); }
  if(!escolar) opt.push(['Incapacidad médica (si aplica)',0,0,10]);
  return base.concat(opt);
};

