  const _tipo = wizard.tipo;
  const _hideForVida = (_tipo === 'VD');
  [_campoFecha,_campoMonto,_campoProv,_campoDesc].forEach(el=>{
    if(!el) return;
    el.classList.toggle('hidden', _hideForVida);
  });
  // Para Salud y AP volvemos a mostrarlos por si venían ocultos
  if(_tipo === 'AP' && _campoProv){ _campoProv.classList.remove('hidden'); }
  
  const contEv = document.querySelector('#w-paso-3, [data-paso="evento"]') || $('f-fecha')?.closest('.grid') || $('f-fecha')?.parentElement?.parentElement;
