const _cargarGenerico = window.cargarGenerico;
window.cargarGenerico = function(store, i, input, maxMB, multi, repintar){
  const existentes = new Set((store[i]||[]).map(s=>s.split(' (')[0]));
  const filtrado = { files: [] };
  for(const f of input.files){
    if(existentes.has(f.name)){ toast('Archivo "'+f.name+'" ya fue cargado.'); continue; }
    filtrado.files.push(f);
  }
  Object.defineProperty(input, 'files', { get:()=>filtrado.files, configurable:true });
  return _cargarGenerico(store, i, input, maxMB, multi, repintar);
};

