function normProv(p){
  const x=(p||'').toLowerCase();
  if(x.includes('bocas')) return 'Bocas del Toro';
  if(x.includes('chiri')||x.includes('david')) return 'Chiriquí';
  if(x.includes('coron')) return 'Coclé';
  if(x.includes('coclé')||x.includes('cocle')||x.includes('penonom')) return 'Coclé';
  if(x.includes('colon')||x.includes('colón')) return 'Colón';
  if(x.includes('darién')||x.includes('darien')) return 'Darién';
  if(x.includes('herre')||x.includes('chitr')) return 'Herrera';
  if(x.includes('los santos')||x.includes('tablas')) return 'Los Santos';
  if(x.includes('oeste')||x.includes('chorrera')||x.includes('chepo')) return 'Panamá Oeste';
  if(x.includes('veraguas')) return 'Veraguas';
  if(x.includes('panam')) return 'Panamá';
  return p||'—';
}
RED.forEach(r=>{ r.pN = normProv(r.p); });
const RED_ESPECIALIDADES = [...new Set(RED.map(r=>r.e).filter(Boolean))].sort();
const RED_PROVINCIAS = [...new Set(RED.map(r=>r.pN))].sort();

/* ================= CERTIFICACIÓN DE PRE-AUTORIZACIÓN (formato Dovela) ================= */
function generarCertPreauth(d){
  // d = objeto con datos de la solicitud aprobada
  const localeTag=window.DovelaI18n?.locales?.[window.DovelaI18n.locale]?.tag || 'es-PA';
  const hoy = new Date().toLocaleDateString(localeTag,{day:'numeric',month:'long',year:'numeric'});
  const w = window.open('', '_blank');
  const css = `
    :root{color-scheme:light;--ink:#0F172A;--primary:#1E3A5F;--secondary:#1D4ED8;--brass:#3B82F6;--line:#CBD5E1;--tint:#F1F5F9;--ivory:#F8FAFC;--muted:#475569;--warn:#B45309;--warn-soft:#FEF3C7}
    body{font-family:"Bricolage Grotesque","Segoe UI",Arial,sans-serif;color:var(--ink);background:#fff;margin:0;padding:0}
    .cert{max-width:820px;margin:0 auto;padding:36px 44px}
    .cert-head{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid var(--brass);padding-bottom:14px;margin-bottom:22px}
    .cert-head img{height:46px;width:auto;display:block}
    h1{font-family:"Fraunces",Georgia,serif;color:var(--primary);font-size:22px;font-weight:600;text-align:center;margin:12px 0 4px}
    h2{font-size:12px;color:var(--secondary);text-align:center;font-weight:700;margin-bottom:20px;text-transform:uppercase;letter-spacing:1.2px}
    table.d{width:100%;border-collapse:collapse;margin-bottom:14px;font-size:12.5px}
    table.d td{border:1px solid var(--line);padding:8px 10px;vertical-align:top}
    table.d td.lbl{background:var(--tint);color:var(--primary);font-weight:700;font-size:10.5px;text-transform:uppercase;letter-spacing:.4px;width:26%}
    .autoriz{background:var(--primary);color:var(--ivory);padding:10px 14px;font-weight:700;font-size:12.5px;letter-spacing:.8px;text-transform:uppercase;border-radius:6px;margin:16px 0 10px}
    .obs{background:var(--warn-soft);border-left:4px solid var(--warn);padding:10px 14px;font-size:12px;line-height:1.55;border-radius:4px;margin:12px 0}
    .firma{margin-top:36px;display:flex;justify-content:space-between;align-items:flex-end;gap:20px}
    .firma .box{flex:1;text-align:center}
    .firma .box .l{border-top:1.5px solid var(--primary);padding-top:6px;font-size:11px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.5px}
    .firma .box b{display:block;font-family:"Fraunces",Georgia,serif;font-size:15px;font-weight:600;color:var(--primary)}
    .foot{margin-top:28px;padding-top:12px;border-top:1px solid var(--line);font-size:10px;color:var(--muted);text-align:center;line-height:1.6}
    .print-btn{position:fixed;top:14px;right:14px;background:var(--primary);color:var(--ivory);border:none;padding:10px 18px;border-radius:999px;font:700 13px "Bricolage Grotesque",Arial,sans-serif;cursor:pointer;box-shadow:0 4px 14px rgba(10,42,48,.2)}
    .print-btn:focus-visible{outline:3px solid var(--brass);outline-offset:3px}
    @media print{.print-btn{display:none}.cert{padding:20px 30px}body{background:#fff}}
  `;
  const html = `<!DOCTYPE html><html lang="${localeTag}"><head><meta charset="UTF-8">
    <title>${i18nT('Certificación PA')} · ${d.num || ""} · Dovela Seguros</title>
    <link rel="stylesheet" href="public/css/dovela-tokens.css">
    <style>${css}</style></head><body>
    <button class="print-btn" onclick="window.print()">${i18nT('Imprimir / PDF')}</button>
    <div class="cert">
      <div class="cert-head">
        <img src="public/assets/brand/dovela-logo-horizontal.svg" width="150" height="46" alt="Dovela Seguros">
        <div style="text-align:right;font-size:11px;color:#334155">
          <div><b>${i18nT('N.º de certificación:')}</b> ${d.num || "—"}</div>
          <div>${i18nT('Emitido:')} ${hoy}</div>
        </div>
      </div>
      <h1>${i18nT('Certificación de Pre-Autorización')}</h1>
      <h2>${i18nT('Hospitalizaciones, cirugías electivas y estudios especiales')}</h2>
      <table class="d">
        <tr><td class="lbl">${i18nT('Fecha')}</td><td>${d.fecha || hoy}</td>
            <td class="lbl">${i18nT('Nombre del paciente')}</td><td>${d.paciente || ""}</td>
            <td class="lbl">${i18nT('Cédula')}</td><td>${d.cedulaPac || d.cedula || ""}</td></tr>
        <tr><td class="lbl">${i18nT('Nombre del asegurado')}</td><td>${d.asegurado || ""}</td>
            <td class="lbl">${i18nT('Colectivo')}</td><td>${d.colectivo || "—"}</td>
            <td class="lbl">${i18nT('N.º de póliza')}</td><td>${d.poliza || "—"}</td></tr>
        <tr><td class="lbl">${i18nT('Sexo del paciente')}</td><td>${i18nT(d.sexo || '')}</td>
            <td class="lbl">${i18nT('Relación con el asegurado')}</td><td>${i18nT(d.parentesco || 'Titular')}</td>
            <td class="lbl">${i18nT('Edad')}</td><td>${d.edad || ""}</td></tr>
      </table>
      <div class="autoriz">${i18nT('Autorización para')}</div>
      <table class="d">
        <tr><td class="lbl">${i18nT('Hospital / Clínica')}</td><td colspan="5">${d.hospital || ""}</td></tr>
        <tr><td class="lbl">${i18nT('Hospitalización')}</td><td>${i18nT(d.hospitalizacion || 'No')}</td>
            <td class="lbl">${i18nT('Estadía promedio')}</td><td>${d.estadia || "—"}</td>
            <td class="lbl">${i18nT('Habitación')}</td><td>${d.habitacion || "—"}</td></tr>
        <tr><td class="lbl">${i18nT('Diagnóstico(s)')}</td><td colspan="5">${d.diagnostico || ""}</td></tr>
        <tr><td class="lbl">${i18nT('Procedimientos')}</td><td colspan="4">${d.procedimientos || ""}</td>
            <td class="lbl">CPT</td></tr>
        ${(d.cptRows || []).map((r) => `<tr><td></td><td colspan="4">${r.desc}</td><td>${r.cpt || ""}</td></tr>`).join("")}
      </table>
      ${d.observaciones ? `<div class="obs"><b>${i18nT('Observaciones / Procedimientos especiales:')}</b><br>${d.observaciones}</div>` : ""}
      <table class="d" style="margin-top:14px">
        <tr><td class="lbl">${i18nT('Lugar de atención')}</td><td>${d.hospital || ""}</td>
            <td class="lbl">${i18nT('Teléfono')}</td><td>${d.telHosp || "—"}</td></tr>
        <tr><td class="lbl">${i18nT('Médico responsable')}</td><td>${d.medico || ""}</td>
            <td class="lbl">${i18nT('Especialidad')}</td><td>${localizeSpecialty(d.especialidad || '') || "—"}</td></tr>
        <tr><td class="lbl">${i18nT('Aprobado por')}</td><td>${d.aprobadoPor || i18nT('Equipo médico evaluador · Dovela Seguros')}</td>
            <td class="lbl">${i18nT('Certificación válida hasta')}</td><td>${d.validaHasta || ""}</td></tr>
      </table>
      <div class="firma">
        <div class="box"><b>Dovela Seguros</b><div class="l">${i18nT('Firma y sello autorizado')}</div></div>
      </div>
      <div class="foot">
        ${i18nT('Documento electrónico generado por el Portal de Autogestión de Dovela Seguros.')}<br>
        ${i18nT('Dovela Seguros es una entidad ficticia con fines demostrativos; este documento no constituye una autorización ni una cobertura real.')}
      </div>
    </div></body></html>`;
  w.document.write(html);
  w.document.close();
}

/* ================= RED MÉDICA (renderer del portal público) ================= */
function renderRed(){
  const q=(document.getElementById('rm-q').value||'').toLowerCase().trim();
  const esp=document.getElementById('rm-esp').value;
  const prov=document.getElementById('rm-prov').value;
  let f=RED;
  if(esp) f=f.filter(r=>r.e===esp);
  if(prov) f=f.filter(r=>r.pN===prov);
  if(q) f=f.filter(r=>(r.n+' '+r.d+' '+r.c+' '+r.e).toLowerCase().includes(q));
  const tb=document.getElementById('rm-body');
  const limit=400;
  tb.innerHTML=f.slice(0,limit).map(r=>`<tr style="border-bottom:1px solid var(--bruma)"><td style="padding:8px 11px;font-size:12.5px;color:var(--text-primary);font-weight:600">${localizeSpecialty(r.e)||'—'}</td><td style="padding:8px 11px">${r.n||'—'}</td><td style="padding:8px 11px;font-size:12px;color:var(--pizarra)">${r.d||'—'}${r.c?', '+r.c:''}</td><td style="padding:8px 11px">${r.pN}</td><td style="padding:8px 11px;font-family:var(--mono);font-size:11.5px">${r.t||'—'}</td></tr>`).join('') || `<tr><td colspan="5" style="padding:24px;text-align:center;color:var(--pizarra)">${i18nT('Sin resultados con esos filtros.')}</td></tr>`;
  const locale=window.DovelaI18n?.locale || 'es';
  const shown=Math.min(f.length,limit), more=f.length>limit;
  const countCopy={
    es:`Mostrando ${shown} de ${f.length} prestadores${more?' (afine su búsqueda para ver más)':''}. Total en red: ${RED.length}.`,
    en:`Showing ${shown} of ${f.length} providers${more?' (refine your search to see more)':''}. Network total: ${RED.length}.`,
    fr:`${shown} prestataires affichés sur ${f.length}${more?' (affinez la recherche pour en voir davantage)':''}. Total du réseau : ${RED.length}.`,
    pt:`Exibindo ${shown} de ${f.length} prestadores${more?' (refine a busca para ver mais)':''}. Total da rede: ${RED.length}.`
  };
  document.getElementById('rm-count').textContent = countCopy[locale] || countCopy.es;
}
function initRed(){
  const se=document.getElementById('rm-esp'), sp=document.getElementById('rm-prov');
  se.insertAdjacentHTML('beforeend', RED_ESPECIALIDADES.map(x=>`<option value="${x}">${localizeSpecialty(x)}</option>`).join(''));
  sp.insertAdjacentHTML('beforeend', RED_PROVINCIAS.map(x=>`<option>${x}</option>`).join(''));
  document.getElementById('rm-q').addEventListener('input',renderRed);
  se.addEventListener('change',renderRed); sp.addEventListener('change',renderRed);
  renderRed();
}
// hook: cuando se entra a v-red
const _irOrig=window.ir;
window.ir=function(v){ _irOrig(v); if(v==='v-red' && !document.getElementById('rm-esp').dataset.ok){ initRed(); document.getElementById('rm-esp').dataset.ok='1'; } };


