function initHomeReveals(){
  if(reducedMotion.matches || !('IntersectionObserver' in window)) return;
  const targets=[...document.querySelectorAll('#v-landing [data-reveal]')];
  const pending=new Set();
  function reveal(target){
    target.classList.add('is-visible');
    pending.delete(target);
    observer.unobserve(target);
    if(!pending.size){
      observer.disconnect();
    }
  }
  const observer=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(!entry.isIntersecting && entry.boundingClientRect.top >= 0) return;
      reveal(entry.target);
    });
  },{rootMargin:'0px 0px -8% 0px',threshold:.08});
  targets.forEach(target=>{
    if(target.getBoundingClientRect().top < window.innerHeight*.9) return;
    target.classList.add('reveal-pending');
    pending.add(target);
    target.addEventListener('focusin',()=>reveal(target),{once:true});
    observer.observe(target);
  });
}
window.requestAnimationFrame(initHomeReveals);

