/* Mobile navigation disclosure: keeps secondary actions reachable without crowding. */
(function initMobileNavigation() {
  const nav = document.querySelector('#v-landing .nav');
  const toggle = document.getElementById('nav-more-toggle');
  const actions = document.getElementById('nav-actions');
  if (!nav || !toggle || !actions) return;

  const mobileQuery = window.matchMedia('(max-width: 600px), (horizontal-viewport-segments: 2)');
  const setOpen = (open, restoreFocus = false) => {
    const isOpen = Boolean(open && mobileQuery.matches);
    nav.dataset.mobileOpen = String(isOpen);
    actions.dataset.mobileOpen = String(isOpen);
    toggle.setAttribute('aria-expanded', String(isOpen));
    toggle.setAttribute('aria-label', i18nT(isOpen ? 'Cerrar más opciones' : 'Abrir más opciones'));
    if (restoreFocus && document.activeElement !== toggle) toggle.focus();
  };

  document.documentElement.classList.add('mobile-nav-ready');
  setOpen(false);

  toggle.addEventListener('click', () => {
    setOpen(toggle.getAttribute('aria-expanded') !== 'true');
  });
  document.addEventListener('click', (event) => {
    if (toggle.getAttribute('aria-expanded') === 'true' && !nav.contains(event.target)) setOpen(false);
  });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') setOpen(false, true);
  });
  actions.addEventListener('click', (event) => {
    if (mobileQuery.matches && event.target.closest('a, [data-tour-open]')) setOpen(false);
  });
  actions.addEventListener('change', (event) => {
    if ((mobileQuery.matches || window.innerWidth <= 600) && event.target.matches('[data-language-select]')) {
      setOpen(false, true);
    }
  });
  document.addEventListener('dovela:navstickychanged', (event) => {
    if (event.detail?.sticky && mobileQuery.matches) setOpen(false);
  });

  const closeOnResize = () => setOpen(false);
  if (mobileQuery.addEventListener) mobileQuery.addEventListener('change', closeOnResize);
  else mobileQuery.addListener(closeOnResize);
})();

/* Sticky landing navigation and an input-independent route back to the page top. */
(function initStickyLandingNavigation() {
  const landing = document.getElementById('v-landing');
  const dock = document.getElementById('nav-dock');
  const nav = dock?.querySelector('.nav');
  const backToTop = document.getElementById('back-to-top');
  if (!landing || !dock || !nav || !backToTop) return;

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let sticky = false;
  let backVisible = false;
  let frame = 0;
  let naturalNavTop = nav.getBoundingClientRect().top + window.scrollY;

  const stickyInset = () => {
    const top = parseFloat(getComputedStyle(nav).top);
    return Number.isFinite(top) ? top : 8;
  };
  const backThreshold = () => Math.max(280, Math.min(520, window.innerHeight * .55));

  const setSticky = (next) => {
    if (next === sticky) return;
    sticky = next;
    if (sticky) landing.appendChild(nav);
    else dock.appendChild(nav);
    nav.classList.toggle('is-sticky', sticky);
    nav.dataset.sticky = String(sticky);
    document.documentElement.classList.toggle('has-sticky-nav', sticky);
    document.dispatchEvent(new CustomEvent('dovela:navstickychanged', { detail: { sticky } }));
  };

  const setBackVisible = (next) => {
    if (next === backVisible) return;
    backVisible = next;
    backToTop.dataset.visible = String(next);
    backToTop.setAttribute('aria-hidden', String(!next));
    backToTop.tabIndex = next ? 0 : -1;
  };

  const update = () => {
    frame = 0;
    const landingVisible = landing.classList.contains('active');
    const y = window.scrollY || document.documentElement.scrollTop;
    setSticky(landingVisible && y > Math.max(2, naturalNavTop - stickyInset()));
    setBackVisible(landingVisible && y > backThreshold());
  };

  const requestUpdate = () => {
    if (!frame) frame = window.requestAnimationFrame(update);
  };

  const refreshMeasurements = () => {
    if (!sticky) naturalNavTop = nav.getBoundingClientRect().top + window.scrollY;
    requestUpdate();
  };

  backToTop.addEventListener('click', () => {
    const finish = () => {
      window.removeEventListener('scrollend', finish);
      window.clearTimeout(focusFallback);
      // Some embedded/mobile engines emit `scrollend` before a native smooth
      // scroll starts. Guarantee the control always fulfils its action.
      if (window.scrollY > 1) window.scrollTo({ top: 0, behavior: 'auto' });
      update();
      nav.focus({ preventScroll: true });
    };
    const focusFallback = window.setTimeout(finish, reducedMotion.matches ? 40 : 1000);
    window.addEventListener('scrollend', finish, { once: true });
    window.scrollTo({ top: 0, behavior: reducedMotion.matches ? 'auto' : 'smooth' });
  });

  window.addEventListener('scroll', requestUpdate, { passive: true });
  window.addEventListener('resize', refreshMeasurements, { passive: true });
  window.addEventListener('orientationchange', refreshMeasurements, { passive: true });
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) refreshMeasurements();
  });

  update();
})();

/* ================= TUTORIAL DE INGRESO =================
   Se muestra en cada ingreso al portal. No se repite dentro de la misma visita: ni al volver
   al inicio, ni al recargar, ni al pasar desde el portal interno (ambos marcan la sesión de la
   pestaña). Nunca se abre sobre el diálogo de idioma: si ese diálogo está visible, espera. */
